        for (i = 0; i < asdl_seq_LEN(o->v.SetComp.generators); i++) {
            if (i)
                dbuf_putc(out, ',');
            if (qp_json_ast_comprehension(ctx, out, asdl_seq_GET(o->v.SetComp.generators, i)) < 0)
                return -1;
        }
        dbuf_putc(out, ']');
        break;
    case DictComp_kind:
        dbuf_putstr(out, "{\"_type\":\"DictComp\",\"key\":");
        if (qp_json_ast_expr(ctx, out, o->v.DictComp.key) < 0)
            return -1;
