static int
qp_json_ast_comprehension(JSContext *ctx, DynBuf *out, comprehension_ty o)
{
    Py_ssize_t i;

    if (!o) {
        dbuf_putstr(out, "null");
        return 0;
    }
    dbuf_putstr(out, "{\"_type\":\"comprehension\",\"target\":");
    if (qp_json_ast_expr(ctx, out, o->target) < 0)
        return -1;
    dbuf_putstr(out, ",\"iter\":");
    if (qp_json_ast_expr(ctx, out, o->iter) < 0)
        return -1;
    dbuf_putstr(out, ",\"ifs\":[");
    for (i = 0; i < asdl_seq_LEN(o->ifs); i++) {
        if (i)
            dbuf_putc(out, ',');
        if (qp_json_ast_expr(ctx, out, asdl_seq_GET(o->ifs, i)) < 0)
            return -1;
    }
    dbuf_putstr(out, "],\"is_async\":");
    dbuf_printf(out, "%d", o->is_async);
    dbuf_putc(out, '}');
    return 0;
}

