static int
qp_json_ast_pattern(JSContext *ctx, DynBuf *out, pattern_ty o)
{
    Py_ssize_t i;

    if (!o) {
        dbuf_putstr(out, "null");
        return 0;
    }
    switch (o->kind) {
    case MatchValue_kind:
        dbuf_putstr(out, "{\"_type\":\"MatchValue\",\"value\":");
        if (qp_json_ast_expr(ctx, out, o->v.MatchValue.value) < 0)
            return -1;
        break;
    case MatchSingleton_kind:
        dbuf_putstr(out, "{\"_type\":\"MatchSingleton\",\"value\":");
        if (qp_json_put_const(ctx, out, o->v.MatchSingleton.value, 1) < 0)
            return -1;
        break;
    case MatchSequence_kind:
        dbuf_putstr(out, "{\"_type\":\"MatchSequence\",\"patterns\":[");
        for (i = 0; i < asdl_seq_LEN(o->v.MatchSequence.patterns); i++) {
            if (i)
                dbuf_putc(out, ',');
            if (qp_json_ast_pattern(ctx, out, asdl_seq_GET(o->v.MatchSequence.patterns, i)) < 0)
                return -1;
        }
        dbuf_putc(out, ']');
        break;
    case MatchMapping_kind:
        dbuf_putstr(out, "{\"_type\":\"MatchMapping\",\"keys\":[");
        for (i = 0; i < asdl_seq_LEN(o->v.MatchMapping.keys); i++) {
            if (i)
                dbuf_putc(out, ',');
            if (qp_json_ast_expr(ctx, out, asdl_seq_GET(o->v.MatchMapping.keys, i)) < 0)
                return -1;
        }
        dbuf_putstr(out, "],\"patterns\":[");
        for (i = 0; i < asdl_seq_LEN(o->v.MatchMapping.patterns); i++) {
            if (i)
                dbuf_putc(out, ',');
            if (qp_json_ast_pattern(ctx, out, asdl_seq_GET(o->v.MatchMapping.patterns, i)) < 0)
                return -1;
        }
        dbuf_putstr(out, "],\"rest\":");
        if (qp_json_put_atom(ctx, out, o->v.MatchMapping.rest) < 0)
            return -1;
        break;
    case MatchClass_kind:
        dbuf_putstr(out, "{\"_type\":\"MatchClass\",\"cls\":");
        if (qp_json_ast_expr(ctx, out, o->v.MatchClass.cls) < 0)
            return -1;
        dbuf_putstr(out, ",\"patterns\":[");
        for (i = 0; i < asdl_seq_LEN(o->v.MatchClass.patterns); i++) {
            if (i)
                dbuf_putc(out, ',');
            if (qp_json_ast_pattern(ctx, out, asdl_seq_GET(o->v.MatchClass.patterns, i)) < 0)
                return -1;
        }
        dbuf_putstr(out, "],\"kwd_attrs\":[");
        for (i = 0; i < asdl_seq_LEN(o->v.MatchClass.kwd_attrs); i++) {
            if (i)
                dbuf_putc(out, ',');
            if (qp_json_put_atom(ctx, out, asdl_seq_GET(o->v.MatchClass.kwd_attrs, i)) < 0)
                return -1;
        }
        dbuf_putstr(out, "],\"kwd_patterns\":[");
        for (i = 0; i < asdl_seq_LEN(o->v.MatchClass.kwd_patterns); i++) {
            if (i)
                dbuf_putc(out, ',');
            if (qp_json_ast_pattern(ctx, out, asdl_seq_GET(o->v.MatchClass.kwd_patterns, i)) < 0)
                return -1;
        }
        dbuf_putc(out, ']');
        break;
    case MatchStar_kind:
        dbuf_putstr(out, "{\"_type\":\"MatchStar\",\"name\":");
        if (qp_json_put_atom(ctx, out, o->v.MatchStar.name) < 0)
            return -1;
        break;
    case MatchAs_kind:
        dbuf_putstr(out, "{\"_type\":\"MatchAs\",\"pattern\":");
        if (qp_json_ast_pattern(ctx, out, o->v.MatchAs.pattern) < 0)
            return -1;
        dbuf_putstr(out, ",\"name\":");
        if (qp_json_put_atom(ctx, out, o->v.MatchAs.name) < 0)
            return -1;
        break;
    case MatchOr_kind:
        dbuf_putstr(out, "{\"_type\":\"MatchOr\",\"patterns\":[");
        for (i = 0; i < asdl_seq_LEN(o->v.MatchOr.patterns); i++) {
            if (i)
                dbuf_putc(out, ',');
            if (qp_json_ast_pattern(ctx, out, asdl_seq_GET(o->v.MatchOr.patterns, i)) < 0)
                return -1;
        }
        dbuf_putc(out, ']');
        break;
    default:
        dbuf_putstr(out, "null");
        return 0;
    }
    dbuf_printf(out, ",\"lineno\":%d,\"col_offset\":%d,\"end_lineno\":%d,\"end_col_offset\":%d}", o->lineno, o->col_offset, o->end_lineno, o->end_col_offset);
    return 0;
}

